// Email Deduplication & Preprocessing
const processedEmails = new Map();
const emailThreads = new Map();
const cleanedEmails = [];

// Helper function to clean email content
function cleanEmailContent(content) {
  if (!content) return '';

  // Remove common signatures and boilerplate
  const signaturePatterns = [
    /--\s*\n[\s\S]*$/,  // Standard signature delimiter
    /_{10,}[\s\S]*$/,   // Underscore separators
    /Sent from my [\w\s]+$/i,  // Mobile signatures
    /Best regards?[\s\S]*$/i,
    /Kind regards?[\s\S]*$/i,
    /Sincerely[\s\S]*$/i,
    /Thanks?[\s\S]*$/i,
    /This email was sent from[\s\S]*$/i,
    /Confidentiality Notice[\s\S]*$/i,
    /CONFIDENTIAL[\s\S]*$/i
  ];

  let cleaned = content;
  signaturePatterns.forEach(pattern => {
    cleaned = cleaned.replace(pattern, '');
  });

  // Remove excessive whitespace
  cleaned = cleaned.replace(/\n{3,}/g, '\n\n');
  cleaned = cleaned.trim();

  return cleaned;
}

// Helper function to detect automated emails
function isAutomatedEmail(email) {
  const automatedPatterns = [
    /no-?reply/i,
    /noreply/i,
    /donotreply/i,
    /auto-?reply/i,
    /notification/i,
    /alert/i,
    /system/i,
    /daemon/i,
    /mailer-daemon/i,
    /postmaster/i
  ];

  const fromEmail = email.from?.toLowerCase() || '';
  const subject = email.subject?.toLowerCase() || '';

  // Check sender patterns
  if (automatedPatterns.some(pattern => pattern.test(fromEmail))) {
    return true;
  }

  // Check subject patterns
  const automatedSubjects = [
    /out of office/i,
    /auto-?reply/i,
    /delivery failure/i,
    /undelivered mail/i,
    /bounce/i,
    /newsletter/i,
    /subscription/i,
    /unsubscribe/i
  ];

  return automatedSubjects.some(pattern => pattern.test(subject));
}

// Helper function to extract email metadata
function extractMetadata(email) {
  return {
    messageId: email.messageId || email['message-id'] || null,
    inReplyTo: email.inReplyTo || email['in-reply-to'] || null,
    references: email.references || [],
    threadId: null, // Will be set during thread reconstruction
    from: email.from,
    to: email.to,
    cc: email.cc || [],
    bcc: email.bcc || [],
    subject: email.subject,
    date: email.date || email.receivedDate,
    hasAttachments: (email.attachments && email.attachments.length > 0) || false,
    attachmentCount: email.attachments ? email.attachments.length : 0,
    priority: email.priority || 'normal',
    isRead: email.flags?.includes('\\Seen') || false,
    isFlagged: email.flags?.includes('\\Flagged') || false,
    folder: email.folder || 'INBOX',
    account: email.account || 'unknown'
  };
}

// Process all input items
for (const item of $input.all()) {
  const email = item.json;

  // Skip if no message ID (can't deduplicate properly)
  const messageId = email.messageId || email['message-id'];
  if (!messageId) {
    console.log('Skipping email without Message-ID');
    continue;
  }

  // Skip if already processed (deduplication)
  if (processedEmails.has(messageId)) {
    console.log(`Skipping duplicate email: ${messageId}`);
    continue;
  }

  // Skip automated emails
  if (isAutomatedEmail(email)) {
    console.log(`Skipping automated email: ${email.subject}`);
    continue;
  }

  // Extract metadata
  const metadata = extractMetadata(email);

  // Clean email content
  const cleanedBody = cleanEmailContent(email.body || email.text || '');
  const cleanedHtml = email.html ? cleanEmailContent(email.html) : null;

  // Skip if content is too short after cleaning
  if (cleanedBody.length < 50 && (!cleanedHtml || cleanedHtml.length < 50)) {
    console.log(`Skipping email with insufficient content: ${email.subject}`);
    continue;
  }

  // Create processed email object
  const processedEmail = {
    ...email,
    metadata,
    cleanedBody,
    cleanedHtml,
    originalBody: email.body || email.text,
    originalHtml: email.html,
    contentLength: cleanedBody.length,
    processedAt: new Date().toISOString()
  };

  // Mark as processed
  processedEmails.set(messageId, processedEmail);
  cleanedEmails.push(processedEmail);
}

// Reconstruct email threads
for (const email of cleanedEmails) {
  const metadata = email.metadata;

  // If email has In-Reply-To, try to find parent
  if (metadata.inReplyTo) {
    const parentEmail = cleanedEmails.find(e => e.metadata.messageId === metadata.inReplyTo);
    if (parentEmail) {
      // Use parent's thread ID or create new one
      metadata.threadId = parentEmail.metadata.threadId || parentEmail.metadata.messageId;
      // Update parent if it doesn't have a thread ID yet
      if (!parentEmail.metadata.threadId) {
        parentEmail.metadata.threadId = parentEmail.metadata.messageId;
      }
    }
  }

  // If no thread ID yet, check references
  if (!metadata.threadId && metadata.references && metadata.references.length > 0) {
    for (const ref of metadata.references) {
      const refEmail = cleanedEmails.find(e => e.metadata.messageId === ref);
      if (refEmail && refEmail.metadata.threadId) {
        metadata.threadId = refEmail.metadata.threadId;
        break;
      }
    }
  }

  // If still no thread ID, use message ID as thread root
  if (!metadata.threadId) {
    metadata.threadId = metadata.messageId;
  }
}

// Group emails by thread for final organization
const threadGroups = new Map();
for (const email of cleanedEmails) {
  const threadId = email.metadata.threadId;
  if (!threadGroups.has(threadId)) {
    threadGroups.set(threadId, []);
  }
  threadGroups.get(threadId).push(email);
}

// Sort emails within threads by date
for (const [threadId, emails] of threadGroups) {
  emails.sort((a, b) => new Date(a.metadata.date) - new Date(b.metadata.date));

  // Add thread position metadata
  emails.forEach((email, index) => {
    email.metadata.threadPosition = index;
    email.metadata.threadLength = emails.length;
    email.metadata.isThreadRoot = index === 0;
  });
}

// Prepare final output with processing statistics
const stats = {
  totalProcessed: cleanedEmails.length,
  totalThreads: threadGroups.size,
  duplicatesRemoved: $input.all().length - cleanedEmails.length,
  averageContentLength: cleanedEmails.reduce((sum, email) => sum + email.contentLength, 0) / cleanedEmails.length || 0
};

console.log('Email processing complete:', stats);

// Return all cleaned emails as separate items
return cleanedEmails.map(email => ({ json: email }));

// Parse LLM Metadata Response and combine with email data
const item = $input.item.json;

// Extract the LLM response (assuming it comes from the previous metadata enrichment chain)
const llmResponse = item.output || item.text || item.response || '';

let parsedMetadata = {};
let parseError = null;

try {
  // Try to parse JSON response from LLM
  if (typeof llmResponse === 'string') {
    // Clean the response - remove markdown code blocks if present
    const cleanedResponse = llmResponse
      .replace(/```json\s*/gi, '')
      .replace(/```\s*/g, '')
      .trim();

    parsedMetadata = JSON.parse(cleanedResponse);
  } else if (typeof llmResponse === 'object') {
    parsedMetadata = llmResponse;
  }
} catch (error) {
  parseError = error.message;
  console.log('Failed to parse LLM metadata response:', error.message);
  console.log('Raw response:', llmResponse);

  // Fallback: try to extract key-value pairs using regex
  try {
    const fallbackMetadata = {};
    const keyValueRegex = /["']?(\w+)["']?\s*:\s*["']?([^,}\n]+)["']?/g;
    let match;

    while ((match = keyValueRegex.exec(llmResponse)) !== null) {
      const key = match[1].toLowerCase();
      const value = match[2].replace(/["']/g, '').trim();
      fallbackMetadata[key] = value;
    }

    if (Object.keys(fallbackMetadata).length > 0) {
      parsedMetadata = fallbackMetadata;
      parseError = null;
    }
  } catch (fallbackError) {
    console.log('Fallback parsing also failed:', fallbackError.message);
  }
}

// Validate and clean extracted metadata
const validatedMetadata = {
  category: parsedMetadata.category || parsedMetadata.type || 'uncategorized',
  importance: parsedMetadata.importance || parsedMetadata.priority || 'medium',
  urgency: parsedMetadata.urgency || 'normal',
  sentiment: parsedMetadata.sentiment || 'neutral',
  keywords: Array.isArray(parsedMetadata.keywords) 
    ? parsedMetadata.keywords 
    : (parsedMetadata.keywords ? parsedMetadata.keywords.split(',').map(k => k.trim()) : []),
  summary: parsedMetadata.summary || parsedMetadata.description || '',
  actionRequired: parsedMetadata.actionRequired || parsedMetadata.action_required || false,
  confidenceScore: parseFloat(parsedMetadata.confidenceScore || parsedMetadata.confidence || 0.5)
};

// Ensure importance is within valid range
const validImportance = ['low', 'medium', 'high', 'critical'];
if (!validImportance.includes(validatedMetadata.importance.toLowerCase())) {
  validatedMetadata.importance = 'medium';
}

// Ensure urgency is within valid range
const validUrgency = ['low', 'normal', 'high', 'urgent'];
if (!validUrgency.includes(validatedMetadata.urgency.toLowerCase())) {
  validatedMetadata.urgency = 'normal';
}

// Ensure sentiment is within valid range
const validSentiment = ['positive', 'neutral', 'negative'];
if (!validSentiment.includes(validatedMetadata.sentiment.toLowerCase())) {
  validatedMetadata.sentiment = 'neutral';
}

// Combine with existing email data
const enrichedEmail = {
  // Original email data
  id: item.id || item.messageId || `email_${Date.now()}`,
  subject: item.subject || '',
  from: item.from || '',
  to: item.to || '',
  date: item.date || item.receivedDate || new Date().toISOString(),
  body: item.body || item.text || item.content || '',

  // Previously extracted data (from categorization and importance scoring)
  category: item.category || validatedMetadata.category,
  importanceScore: item.importanceScore || item.importance || validatedMetadata.importance,

  // Newly parsed and validated metadata
  metadata: validatedMetadata,

  // Processing information
  processingInfo: {
    parsedAt: new Date().toISOString(),
    parseError: parseError,
    rawLlmResponse: llmResponse,
    hasValidMetadata: Object.keys(parsedMetadata).length > 0
  }
};

// Add quality score based on metadata completeness
const metadataFields = Object.keys(validatedMetadata);
const completedFields = metadataFields.filter(field => {
  const value = validatedMetadata[field];
  return value !== null && value !== undefined && value !== '' && 
         (Array.isArray(value) ? value.length > 0 : true);
});

enrichedEmail.qualityScore = completedFields.length / metadataFields.length;

return { json: enrichedEmail };
